/**
 * bundle-liteparse.js
 * Reads @llamaindex/liteparse-wasm/pkg/ and generates a self-contained
 * HTML string (with WASM base64-inlined) that runs inside a hidden WebView.
 *
 * Run: node scripts/bundle-liteparse.js
 * Output: src/core/liteparse/liteparseWebBundle.ts
 *
 * The WebView has a real browser engine → full WebAssembly support on both
 * iOS and Android. No Polygen needed. Zero network (WASM is bundled offline).
 */
const fs = require('fs');
const path = require('path');

const PKG = path.join(__dirname, '../node_modules/@llamaindex/liteparse-wasm/pkg');
const OUT = path.join(__dirname, '../src/core/liteparse/liteparseWebBundle.ts');

const jsSource = fs.readFileSync(path.join(PKG, 'liteparse_wasm.js'), 'utf8');
const wasmBytes = fs.readFileSync(path.join(PKG, 'liteparse_wasm_bg.wasm'));
const wasmBase64 = wasmBytes.toString('base64');

// Convert ESM exports to a global variable the WebView HTML can use
// The wasm-bindgen output uses `export class LiteParse` — we wrap it in an IIFE
const patchedJs = jsSource
  .replace(/^export\s+/gm, '')           // remove all 'export' keywords
  .replace(/^import\s+.*?;$/gm, '');     // remove import statements

const html = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"></head>
<body>
<script>
// ── WASM binary (base64 inlined for offline use) ──────────────────────────
const WASM_BASE64 = "${wasmBase64}";

function base64ToBytes(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

// ── Patched liteparse_wasm.js (ESM → global) ──────────────────────────────
${patchedJs}

// ── Override WASM loader to use inlined base64 ───────────────────────────
async function initWasm() {
  const wasmBytes = base64ToBytes(WASM_BASE64);
  // wasm-bindgen init() accepts a BufferSource directly
  await init(wasmBytes.buffer);
}

// ── Message bridge ────────────────────────────────────────────────────────
let ready = false;
const queue = [];

async function setup() {
  try {
    await initWasm();
    ready = true;
    window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'ready' }));
    queue.forEach(processMessage);
    queue.length = 0;
  } catch(e) {
    window.ReactNativeWebView.postMessage(JSON.stringify({
      type: 'error', message: 'init failed: ' + e.message
    }));
  }
}

async function processMessage(msg) {
  const { type, id, base64, ocrText } = msg;
  if (type !== 'parse') return;
  try {
    const bytes = base64ToBytes(base64);
    const parser = new LiteParse({ ocrEnabled: false, outputFormat: 'json' });
    const json = await parser.parse(bytes);
    window.ReactNativeWebView.postMessage(JSON.stringify({
      type: 'result', id, result: json
    }));
  } catch(e) {
    window.ReactNativeWebView.postMessage(JSON.stringify({
      type: 'result', id, error: e.message
    }));
  }
}

document.addEventListener('message', function(e) {
  const msg = JSON.parse(e.data);
  if (!ready) { queue.push(msg); return; }
  processMessage(msg);
});

window.addEventListener('message', function(e) {
  const msg = JSON.parse(e.data);
  if (!ready) { queue.push(msg); return; }
  processMessage(msg);
});

setup();
</script>
</body>
</html>`;

const output = `// AUTO-GENERATED by scripts/bundle-liteparse.js — do not edit manually
// Re-run: node scripts/bundle-liteparse.js
// @llamaindex/liteparse-wasm bundled offline for WebView (iOS + Android)

export const LITEPARSE_WEB_HTML = ${JSON.stringify(html)};
`;

fs.writeFileSync(OUT, output, 'utf8');
const kb = Math.round(Buffer.byteLength(output) / 1024);
console.log('Generated:', OUT);
console.log('Bundle size:', kb, 'KB');
